"""The tested versions' pure rules (scripts/tested_versions.py): reading an export, the pins block, the refresh day,
what a refresh changed. uv itself isn't run here; scripts/check.sh runs the script's check on the real lock."""

from __future__ import annotations

import pytest
import tested_versions as tv

EXPORTED = """\
# This file was autogenerated by uv
-e ./hirocli
cffi==2.0.0 ; platform_python_implementation != 'PyPy'
cryptography==47.0.0

numpy==2.4.4
"""

PYPROJECT = f"""\
[project]
dependencies = [
    "hirocli~=0.2.0",
{tv.START}
    "old==1.0",
{tv.END}
]
"""


def test_an_export_gives_its_pins_with_their_markers_and_nothing_else() -> None:
    assert tv.requirements(EXPORTED) == ["cffi==2.0.0 ; platform_python_implementation != 'PyPy'",
                                         "cryptography==47.0.0", "numpy==2.4.4"]


def test_the_pins_block_is_replaced_and_the_rest_kept() -> None:
    text = tv.with_pins(PYPROJECT, ["a==1", "b==2 ; sys_platform == 'linux'"], "2026-11-27")
    assert '"hirocli~=0.2.0",' in text and "old==1.0" not in text
    assert (f'{tv.START}\n    # Refreshed to the latest: 2026-11-27 (uv lock --upgrade)\n    "a==1",\n'
            f'    "b==2 ; sys_platform == \'linux\'",\n{tv.END}\n]') in text
    assert tv.with_pins(text, [], None).count('"') == 2  # emptied: only hirocli's


def test_a_pyproject_without_the_block_is_refused_in_words() -> None:
    with pytest.raises(tv.Refused, match="no tested-versions block"):
        tv.with_pins('[project]\ndependencies = ["hirocli"]\n', ["a==1"], None)


def test_the_block_says_the_day_the_lock_was_refreshed() -> None:
    assert tv.refreshed(tv.with_pins(PYPROJECT, ["a==1"], "2026-11-27")) == "2026-11-27"
    never = tv.with_pins(PYPROJECT, ["a==1"], None)
    assert "Refreshed to the latest: never" in never and tv.refreshed(never) is None
    assert tv.refreshed(PYPROJECT) is None


def test_a_refresh_names_what_moved_came_and_went() -> None:
    before = {"cryptography": "47.0.0", "numpy": "2.4.4", "gone": "1.0", "same": "3"}
    after = {"cryptography": "50.0.2", "numpy": "2.5.5", "new": "0.1", "same": "3"}
    assert tv.changes(before, after) == ["cryptography: 47.0.0 → 50.0.2", "gone: gone", "new: 0.1 (new)",
                                         "numpy: 2.4.4 → 2.5.5"]


def test_a_package_locked_at_two_versions_keeps_both() -> None:
    lock = 'version = 1\n[[package]]\nname = "numpy"\nversion = "2.2.6"\n[[package]]\nname = "numpy"\nversion = "2.4.4"\n'
    assert tv.versions(lock) == {"numpy": "2.2.6, 2.4.4"}
